 uint256 _return;
 if(state == State.PreIco){
 _return = _wei.add(_wei.div(3));
 }
 else {
 if(raisedWei < targetRaisedWei){
 _return = _wei;
 } else {
 _return = _wei.mul(targetRaisedWei).div(raisedWei);
 }
 }
 return _return.div(10 ** 12);
 }

