code.MiniMeToken.generateTokens(address,uint2:
function generateTokens(address _owner, uint256 _amount
 ) onlyController returns (bool) {
 uint256 curTotalSupply = totalSupply();
 require(curTotalSupply + _amount >= curTotalSupply);
 uint256 previousBalanceTo = balanceOf(_owner);
 require(previousBalanceTo + _amount >= previousBalanceTo);
 updateValueAtNow(totalSupplyHistory, curTotalSupply + _amount);
 updateValueAtNow(balances[_owner], previousBalanceTo + _amount);
 Transfer(0, _owner, _amount);
 return true;
 }

code.MiniMeToken.approve(address,uint256):
function approve(address _spender, uint256 _amount) returns (bool success) {
 require(transfersEnabled);
 require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
 if (isContract(controller)) {
 require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
 }
 allowed[msg.sender][_spender] = _amount;
 Approval(msg.sender, _spender, _amount);
 return true;
 }

code.MiniMeToken.balanceOfAt(address,uint256):
function balanceOfAt(address _owner, uint256 _blockNumber) constant
 returns (uint) {
 if ((balances[_owner].length == 0)
 || (balances[_owner][0].fromBlock > _blockNumber)) {
 if (address(parentToken) != 0) {
 return parentToken.balanceOfAt(_owner, min(_blockNumber, parentSnapShotBlock));
 } else {
 return 0;
 }
 } else {
 return getValueAt(balances[_owner], _blockNumber);
 }
 }

code.MiniMeToken.doTransfer(address,address,u:
function doTransfer(address _from, address _to, uint256 _amount
 ) internal returns(bool) {
 if (_amount == 0) {
 return true;
 }
 require(parentSnapShotBlock < block.number);
 require((_to != 0) && (_to != address(this)));
 var previousBalanceFrom = balanceOfAt(_from, block.number);
 if (previousBalanceFrom < _amount) {
 return false;
 }
 if (isContract(controller)) {
 require(TokenController(controller).onTransfer(_from, _to, _amount));
 }
 updateValueAtNow(balances[_from], previousBalanceFrom - _amount);
 var previousBalanceTo = balanceOfAt(_to, block.number);
 require(previousBalanceTo + _amount >= previousBalanceTo);
 updateValueAtNow(balances[_to], previousBalanceTo + _amount);
 Transfer(_from, _to, _amount);
 return true;
 }

